// src/pages/MeetingRoom.js

import { useState, useEffect, useRef } from "react";

// ==================================================
// 테스트용 방장 여부
//
// true  → 방장
// false → 일반 참가자
// ==================================================

const TEST_IS_HOST = true;


function MeetingRoom() {

  // ==================================================
  // 모임 정보
  // ==================================================

  const roomTitle = "상실과 성장에 대하여";
  const roomMood = "badge1";


  // ==================================================
  // 방장 여부
  // ==================================================

  const isHost = TEST_IS_HOST;


  // ==================================================
  // 입력
  // ==================================================

  const [input, setInput] = useState("");


  // ==================================================
  // AI 로딩
  // ==================================================

  const [aiLoading, setAiLoading] =
    useState(false);


  // ==================================================
  // 메시지
  // ==================================================

  const [messages, setMessages] = useState([

    {
      id: 1,
      user: "AI",
      type: "ai",
      text:
        "모임원들의 독후감과 기록을 먼저 정리했어요 ✨\n\n• 외로움과 연결감\n• 상실 이후의 성장\n• 잔잔하지만 깊은 감정선\n• 현실적인 인간 관계",
    },

    {
      id: 2,
      user: "AI",
      type: "ai",
      text:
        "오늘은 가장 기억에 남았던 문장을 함께 이야기해볼게요 🙂",
    },

    {
      id: 3,
      user: "민지",
      type: "other",
      color: "#FFB6C1",
      text:
        "저는 마지막 장면이 가장 슬펐어요.",
    },

    {
      id: 4,
      user: "현우",
      type: "other",
      color: "#87CEEB",
      text:
        "문장이 진짜 고요해서 좋았어요.",
    },

    {
      id: 5,
      user: "서연",
      type: "other",
      color: "#C3E88D",
      text:
        "와타나베 감정선이 너무 현실적이었어요.",
    },

  ]);


  // ==================================================
  // 채팅 마지막 위치
  // ==================================================

  const chatEndRef = useRef(null);


  // ==================================================
  // 메시지 추가 → 아래로 자동 스크롤
  // ==================================================

  useEffect(() => {

    chatEndRef.current?.scrollIntoView({
      behavior: "smooth",
      block: "end",
    });

  }, [messages]);


  // ==================================================
  // 일반 메시지 보내기
  // ==================================================

  const sendMessage = () => {

    const text = input.trim();

    if (!text) {
      return;
    }


    const myMessage = {

      id: Date.now(),

      user: "나",

      type: "me",

      text: text,

    };


    setMessages((prev) => [
      ...prev,
      myMessage,
    ]);


    setInput("");

  };


  // ==================================================
  // AI 진행자 요청
  // ==================================================

  const requestAI = async () => {

    if (!isHost) {
      return;
    }


    if (aiLoading) {
      return;
    }


    setAiLoading(true);


    // 현재 대화 내용

    const conversation =
      messages.map((message) => ({
        user: message.user,
        type: message.type,
        text: message.text,
      }));


    // 나중에 백엔드로 전달할 데이터

    const requestData = {

      roomTitle:
        roomTitle,

      mood:
        roomMood,

      messages:
        conversation,

    };


    console.log(
      "AI 진행자 요청 데이터:",
      requestData
    );


    // ==================================================
    // 현재는 프론트 테스트용
    // ==================================================

    setTimeout(() => {

      const aiReply = {

        id: Date.now(),

        user: "AI",

        type: "ai",

        text:
          "좋은 의견들이 나오고 있네요 🌿\n\n지금까지 이야기한 내용을 보면 인물의 감정과 상실에 대한 이야기가 많이 나온 것 같아요.\n\n여러분은 이 책에서 가장 공감했던 인물의 감정이 무엇이었나요?",

      };


      setMessages((prev) => [
        ...prev,
        aiReply,
      ]);


      setAiLoading(false);

    }, 500);

  };


  // ==================================================
  // 화면
  // ==================================================

  return (

    <div
      style={{

        width: "100%",

        maxWidth: "430px",

        /*
         * ★ 중요
         *
         * 화면 전체 높이를 사용
         */
        height: "100vh",

        margin: "0 auto",

        display: "flex",

        flexDirection: "column",

        background: "#ffffff",

        boxSizing: "border-box",

        /*
         * 전체 페이지가 아래로 늘어나지 않게 함
         */
        overflow: "hidden",

      }}
    >


      {/* ==================================================
          헤더
      ================================================== */}

      <div
        className="meeting-header"
        style={{

          /*
           * 헤더는 고정
           */
          flexShrink: 0,

        }}
      >

        <div className="meeting-room-name">
          📚 {roomTitle}
        </div>

      </div>


      {/* ==================================================
          ★ 채팅 영역
          
          여기가 핵심
          
          flex: 1
          minHeight: 0
          overflowY: auto
          
          → 남은 공간만 차지하고
          → 메시지가 많아지면 여기만 스크롤
      ================================================== */}

      <div
        className="meeting-chat-area"
        style={{

          flex: "1 1 0",

          minHeight: 0,

          height: 0,

          overflowY: "auto",

          overflowX: "hidden",

          boxSizing: "border-box",

          padding:
            "15px 14px 20px",

        }}
      >

        {messages.map((msg) => (

          <div
            key={msg.id}
            className={`chat-row ${
              msg.type === "me"
                ? "right"
                : "left"
            }`}
          >

            {/* 프로필 */}

            {msg.type !== "me" && (

              <div
                className="chat-profile"
                style={{

                  background:
                    msg.type === "ai"
                      ? "#9bd44e"
                      : msg.color,

                }}
              >
                {msg.user[0]}
              </div>

            )}


            {/* 이름 + 말풍선 */}

            <div className="chat-content">

              {msg.type !== "me" && (

                <div className="chat-name">
                  {msg.user}
                </div>

              )}


              <div
                className={`chat-bubble ${
                  msg.type === "me"
                    ? "user-chat"
                    : msg.type === "ai"
                    ? "ai-chat"
                    : "other-chat"
                }`}
                style={{
                  whiteSpace: "pre-line",
                }}
              >
                {msg.text}
              </div>

            </div>

          </div>

        ))}


        {/* 자동 스크롤 위치 */}

        <div ref={chatEndRef} />

      </div>


      {/* ==================================================
          ★ AI 진행자 버튼
          
          방장에게만 표시
          
          채팅 영역 밖에 있기 때문에
          채팅 스크롤과 같이 움직이지 않음
      ================================================== */}

      {isHost && (

        <div
          style={{

            flexShrink: 0,

            width: "100%",

            padding:
              "8px 12px",

            background:
              "#ffffff",

            borderTop:
              "1px solid #eeeeee",

            boxSizing:
              "border-box",

          }}
        >

          <button
            type="button"

            onClick={requestAI}

            disabled={aiLoading}

            style={{

              width: "100%",

              height: "44px",

              border: "none",

              borderRadius: "14px",

              background:
                aiLoading
                  ? "#e5e5e5"
                  : "#eef7da",

              color:
                aiLoading
                  ? "#999999"
                  : "#6a8c2f",

              fontSize: "14px",

              fontWeight: "700",

              cursor:
                aiLoading
                  ? "default"
                  : "pointer",

              display: "flex",

              alignItems: "center",

              justifyContent: "center",

              boxSizing:
                "border-box",

            }}
          >

            {aiLoading
              ? "✨ AI가 생각하고 있어요..."
              : "✨ AI 진행자에게 질문하기"}

          </button>

        </div>

      )}


      {/* ==================================================
          채팅 입력창
          
          이것도 고정
      ================================================== */}

      <div
        className="meeting-input-wrap"
        style={{

          flexShrink: 0,

          width: "100%",

          boxSizing:
            "border-box",

        }}
      >

        <input
          value={input}

          onChange={(e) =>
            setInput(
              e.target.value
            )
          }

          placeholder="생각을 입력해보세요"

          onKeyDown={(e) => {

            if (
              e.key === "Enter"
            ) {

              e.preventDefault();

              sendMessage();

            }

          }}
        />

        <button
          type="button"
          onClick={sendMessage}
        >
          전송
        </button>

      </div>


    </div>

  );
}


export default MeetingRoom;
